// Declare necessary variables
int largestSubstringLen = 0;
String largestSubstring = "";

// Iterate through each string in the list
for (String str : strings) {

    // Check if the string is a substring of any other string
    for (String otherStr : strings) {

        // If the string is a substring of another string
        if (otherStr.contains(str)) {

            // Check if the string or its inverse is a substring of any other string
            if (otherStr.contains(str) || otherStr.contains(str.toUpperCase())) {

                // If the string or its inverse is a substring of any other string
                largestSubstring = str;
                largestSubstringLen = str.length();
                break;
            }
        }
    }
}

// Return the length of the largest substring
return largestSubstringLen;
}

