public static int countOilDeposits(char[][] grid) {
  int n = grid.length;
  int m = grid[0].length;
  int count = 0;

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (grid[i][j] == '@') {
        // Found an oil deposit, mark it as visited and count it
        grid[i][j] = '*';
        count++;

        // Recursively search for more oil deposits in the 4-way adjacent cells
        if (i > 0 && grid[i - 1][j] == '@') {
          count += countOilDeposits(grid, i - 1, j);
        }
        if (j > 0 && grid[i][j - 1] == '@') {
          count += countOilDeposits(grid, i, j - 1);
        }
        if (i < n - 1 && grid[i + 1][j] == '@') {
          count += countOilDeposits(grid, i + 1, j);
        }
        if (j < m - 1 && grid[i][j + 1] == '@') {
          count += countOilDeposits(grid, i, j + 1);
        }
      }
    }
  }

  return count;
}

