public static String convertDatesToWeekdays(String date) {
    String[] monthDays = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String[] dateParts = date.split(" ");
    String month = monthDays[Integer.parseInt(dateParts[0]) - 1];
    String day = dateParts[1];
    String year = dateParts[2];
    String weekday = weekdays[ Integer.parseInt(new SimpleDateFormat("dd-MM-yyyy", Locale.ENGLISH).format(new Date(year, month, day))) % 7 ];
