public int minInsertions(String s) {
    int count = 0;
    Stack<Character> stack = new Stack<>();
    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.push('(');
        } else {
            if (stack.isEmpty() || stack.pop() != '(') {
                count++;
            }
        }
    }
    while (!stack.isEmpty()) {
        count++;
        stack.pop();
    }
    return count;
}

