public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] dp = new int[n];
    dp[0] = 1;
    Set<String> splits = new HashSet<>();
    for (int i = 1; i < n; i++) {
        int max = 0;
        for (int j = 0; j < i; j++) {
            if (s.charAt(i) == s.charAt(j)) continue;
            int k = j + 1;
            while (k < i && s.charAt(i) != s.charAt(k)) k++;
            if (k == i) {
                max = Math.max(max, dp[j]);
                splits.add(s.substring(j, k));
            }
        }
        dp[i] = max + 1;
    }
    return dp[n - 1];
}

