public String getSmallestString(int n, int k) {
    // Convert k to a character string
    String kStr = String.valueOf(k);
    // Pad kStr with leading zeros to make it of length n
    kStr = String.format("%0" + n + "d", Integer.parseInt(kStr));
    // Generate a sequence of characters from 'a' to 'z'
    char[] chars = new char[26];
    for (int i = 0; i < 26; i++) {
        chars[i] = (char) (i + 97);
    }
    // Create a map of characters to their positions in the alphabet
    Map<Character, Integer> charMap = new HashMap<>();
    for (int i = 0; i < 26; i++) {
        charMap.put(chars[i], i + 1);
    }
    // Use the map to calculate the value of each character in the padded kStr
    int[] values = new int[n];
    for (int i = 0; i < n; i++) {
        values[i] = charMap.get(kStr.charAt(i)) * Math.pow(26, n - i - 1);
