    // Find the character with the smallest value and remove it from the string
    int minValue = Integer.MAX_VALUE;
    int minIndex = -1;
    for (int i = 0; i < n; i++) {
        if (values[i] < minValue) {
            minValue = values[i];
            minIndex = i;
        }
    }
    kStr = kStr.substring(0, minIndex) + kStr.substring(minIndex + 1);
    // Return the lexicographically smallest string of length n and value k
    return kStr;
}

